"use strict";(self.webpackChunk_711=self.webpackChunk_711||[]).push([[857],{857(e,n,a){a.r(n),a.d(n,{default:()=>o}),a.dn(o);var s=a(540);function o(){return s.createElement("div",{className:"markdown",dangerouslySetInnerHTML:{__html:'<style>\n.markdown h3, .markdown h4 {\n    margin: 0;\n}\n\n.markdown > div.hero {\n    display: flex;\n    flex-flow: column nowrap;\n    justify-content: flex-end;\n    width: 100%;\n    height: 20vh;\n    background: url("/images/workshops-hero.jpg") center / cover no-repeat;\n}\n\n.markdown > div.hero > p.caption {\n    text-align: end;\n    font-size: 12px;\n    margin: 0;\n    text-shadow: 1px 1px 1px black;\n}\n</style>\n\n<h1>Ingleside Workshops</h1>\n<div class="hero">\n    <p class="caption">\n        c/o <a href="https://www.omorivisuals.com/">\n            Omori Visuals\n        </a>\n    </p>\n</div>\n\n<p>Free skill-sharing workshops led by neigborhood volunteers. Learn skills through\nhands-on activities, meet your neighbors, and win raffle prizes.</p>\n<p>Unless noted below, all workshops meet at <a href="https://maps.app.goo.gl/uN9Pn3cHbAcrm66YA">Unity Plaza</a>, and\ntake ~1hr.</p>\n<p>Questions or comments? Email us at: <a href="mailto:711@ingleside.co?subject=workshops">711@ingleside.co</a><br />\nFollow us on Instagram: <a href="https://instagram.com/711.ingleside">711.ingleside</a></p>\n<p>Subscribe to our calendar to see upcoming events:<br />\n<a href="https://calendar.google.com/calendar/u/6?cid=ZjE4MTc2ODM1ZjZjMDE3YmQxNDdhN2Y1MTQwODg1YTE2MDFjYTYxZTM1ZDE5NGExMjE4ODcxNTEwZjgyZjkzNUBncm91cC5jYWxlbmRhci5nb29nbGUuY29t">Google</a> |\n<a href="https://calendar.google.com/calendar/ical/f18176835f6c017bd147a7f5140885a1601ca61e35d194a1218871510f82f935%40group.calendar.google.com/public/basic.ics">iCal (Apple)</a></p>\n<hr>\n<h3>Plant swap</h3>\n<h4>September 12 | 10:30am-11:30am</h4>\n<p>Thanks to <a href="https://sfpl.org/events/2026/09/12/social-plant-swap">San Francisco Public Library</a> for running this\nevent!<br><strong>September 12&#39;s plant swap will be hosted at <a href="https://maps.app.goo.gl/uN9Pn3cHbAcrm66YA">Unity Plaza</a></strong>.</p>\n<p>Bring your cuttings, seedlings, surplus harvest, or plants that need a new home\nto swap with other gardeners.</p>\n<p>All types of plants welcome; please label if possible.</p>\n<p>Thanks to <a href="https://alemanyfarm.org/">Friends of Alemany Farms</a>, who will be doing a plant\nstarter giveaway at 11:00am!</p>\n<hr>\n<p><a href="./archive/">Click here to see the list of past workshops.</a></p>\n<h2>Feedback and volunteering</h2>\n<p>All of our workshops are organized and led by volunteers! If you have:</p>\n<ul>\n<li>feedback on the teaching or learning experience</li>\n<li>suggestions on topics for future workshops</li>\n<li>interest in volunteering</li>\n</ul>\n<p>Please email us at:</p>\n<p><a href="mailto:711@ingleside.co?subject=workshops+feedback"><address>711@ingleside.co</address></a></p>\n'}})}}}]);
